function numFactoredBinaryTrees(arr: number[]): number {
    const MOD = 1000000007n;
    arr.sort((a, b) => a - b);

    const dp = new Map<number, bigint>();
    let total = 0n;

    for (let i = 0; i < arr.length; i++) {
        const value = arr[i];
        let count = 1n;

        for (let j = 0; j < i; j++) {
            const left = arr[j];
            if (value % left !== 0) continue;

            const rightCount = dp.get(value / left);
            if (rightCount !== undefined) {
                count = (count + dp.get(left)! * rightCount) % MOD;
            }
        }

        dp.set(value, count);
        total = (total + count) % MOD;
    }

    return Number(total);
};
```

