function countVowelPermutation(n: number): number {
    const MOD = 1_000_000_007;
    let a = 1, e = 1, i = 1, o = 1, u = 1;

    for (let length = 2; length <= n; length++) {
        const nextA = (e + i + u) % MOD;
        const nextE = (a + i) % MOD;
        const nextI = (e + o) % MOD;
        const nextO = i;
        const nextU = (i + o) % MOD;

        a = nextA;
        e = nextE;
        i = nextI;
        o = nextO;
        u = nextU;
    }

    return (a + e + i + o + u) % MOD;
};
