class MKAverage {
    private readonly m: number;
    private readonly k: number;
    private readonly limit = 100000;
    private readonly counts: Int32Array;
    private readonly sums: Float64Array;
    private readonly window: Int32Array;
    private size = 0;
    private next = 0;

    constructor(m: number, k: number) {
        this.m = m;
        this.k = k;
        this.counts = new Int32Array(this.limit + 1);
        this.sums = new Float64Array(this.limit + 1);
        this.window = new Int32Array(m);
    }

    addElement(num: number): void {
        if (this.size === this.m) {
            this.update(this.window[this.next], -1);
        } else {
            this.size++;
        }

        this.window[this.next] = num;
        this.next = (this.next + 1) % this.m;
        this.update(num, 1);
    }

    calculateMKAverage(): number {
        if (this.size < this.m) {
            return -1;
        }

        const middleSum =
            this.sumSmallest(this.m - this.k) - this.sumSmallest(this.k);

        return Math.floor(middleSum / (this.m - 2 * this.k));
    }

    private update(value: number, delta: number): void {
        for (let i = value; i <= this.limit; i += i & -i) {
            this.counts[i] += delta;
            this.sums[i] += value * delta;
        }
    }

    // Returns the sum of the smallest rank elements, including duplicates.
    private sumSmallest(rank: number): number {
        let index = 0;
        let count = 0;
        let sum = 0;

        // Binary lifting over the Fenwick tree.
        for (let step = 1 << 16; step > 0; step >>= 1) {
            const nextIndex = index + step;

            if (
                nextIndex <= this.limit &&
                count + this.counts[nextIndex] < rank
            ) {
                index = nextIndex;
                count += this.counts[nextIndex];
                sum += this.sums[nextIndex];
            }
        }

        return sum + (rank - count) * (index + 1);
    }
}

