function canCross(stones: number[]): boolean {
    const n = stones.length;

    for (let i = 1; i < n; i++) {
        if (stones[i] - stones[i - 1] > i) {
            return false;
        }
    }

    // dp[i][k] indicates whether stone i is reachable with a jump of k units.
    const dp = Array.from({ length: n }, () => new Uint8Array(n + 1));
