    private readonly maxSize: number;
    private values: number[] = [];
    private pending: number[] = [];

    constructor(maxSize: number) {
        this.maxSize = maxSize;
    }

    push(x: number): void {
        if (this.values.length >= this.maxSize) return;

        this.values.push(x);
        this.pending.push(0);
    }

    pop(): number {
        const top = this.values.length - 1;
        if (top < 0) return -1;

        const extra = this.pending.pop()!;
        if (top > 0) {
            this.pending[top - 1] += extra;
        }

        return this.values.pop()! + extra;
