function maxRunTime(n: number, batteries: number[]): number {
    let total = 0;
    for (const capacity of batteries) {
        total += capacity;
    }

    let low = 0;
    let high = Math.floor(total / n);

    while (low < high) {
        const mid = low + Math.ceil((high - low) / 2);
        const required = n * mid;
        let available = 0;

        for (const capacity of batteries) {
            available += Math.min(capacity, mid);
            if (available >= required) break;
        }

        if (available >= required) {
            low = mid;
        } else {
            high = mid - 1;
        }
    }

    return low;
};
