function minMalwareSpread(graph: number[][], initial: number[]): number {
    const n = graph.length;
    const infected = new Uint8Array(n);
    for (const node of initial) {
        infected[node] = 1;
    }

    const component = new Int32Array(n);
    component.fill(-1);
    const sizes: number[] = [];

    for (let start = 0; start < n; start++) {
        if (infected[start] || component[start] !== -1) continue;

        const id = sizes.length;
        const stack: number[] = [start];
        component[start] = id;
        let size = 0;

        while (stack.length > 0) {
            const node = stack.pop()!;
            size++;

            for (let next = 0; next < n; next++) {
                if (
                    graph[node][next] === 1 &&
                    !infected[next] &&
                    component[next] === -1
                ) {
                    component[next] = id;
                    stack.push(next);
                }
            }
        }

        sizes.push(size);
    }

    // -1: no infection source; -2: multiple distinct infection sources.
    const owner = new Int32Array(sizes.length);
    owner.fill(-1);

    for (const source of initial) {
        for (let node = 0; node < n; node++) {
            if (infected[node] || graph[source][node] === 0) continue;

            const id = component[node];
            if (owner[id] === -1) {
