function minCost(maxTime: number, edges: number[][], passingFees: number[]): number {
    const n = passingFees.length;
    // dp[time * n + city] is the minimum cost to arrive at exactly this time.
    const dp = new Float64Array((maxTime + 1) * n);
    dp.fill(Infinity);
    dp[0] = passingFees[0];

    let answer = Infinity;

    for (let time = 1; time <= maxTime; time++) {
        const current = time * n;

        for (const [u, v, travelTime] of edges) {
            if (travelTime > time) continue;

            const previous = (time - travelTime) * n;

            dp[current + v] = Math.min(
                dp[current + v],
                dp[previous + u] + passingFees[v]
            );

            dp[current + u] = Math.min(
                dp[current + u],
                dp[previous + v] + passingFees[u]
            );
        }

        answer = Math.min(answer, dp[current + n - 1]);
    }

    return answer === Infinity ? -1 : answer;
};
