function numOfWays(nums: number[]): number {
    const MOD = 1000000007n;
    const n = nums.length;

    const modPow = (base: bigint, exponent: bigint): bigint => {
        let result = 1n;
        while (exponent > 0n) {
            if ((exponent & 1n) !== 0n) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exponent >>= 1n;
        }
        return result;
    };

    const factorial: bigint[] = new Array(n + 1).fill(1n);
    const inverseFactorial: bigint[] = new Array(n + 1).fill(1n);

    for (let i = 1; i <= n; i++) {
        factorial[i] = (factorial[i - 1] * BigInt(i)) % MOD;
    }

    inverseFactorial[n] = modPow(factorial[n], MOD - 2n);
    for (let i = n; i > 0; i--) {
        inverseFactorial[i - 1] =
            (inverseFactorial[i] * BigInt(i)) % MOD;
    }

    // Nodes are indexed by their insertion positions.
    const left = new Int32Array(n).fill(-1);
    const right = new Int32Array(n).fill(-1);

    for (let i = 1; i < n; i++) {
        let current = 0;

        while (true) {
            const children = nums[i] < nums[current] ? left : right;
            if (children[current] === -1) {
                children[current] = i;
                break;
            }
            current = children[current];
        }
    }

    const size = new Int32Array(n);
    const ways: bigint[] = new Array(n).fill(1n);

    // Children were inserted after their parents, so process in reverse.
    for (let i = n - 1; i >= 0; i--) {
        const l = left[i];
        const r = right[i];
        const leftSize = l === -1 ? 0 : size[l];
        const rightSize = r === -1 ? 0 : size[r];

        size[i] = 1 + leftSize + rightSize;

        // Choose positions for the left subtree among all non-root nodes.
        let count = factorial[leftSize + rightSize];
        count = (count * inverseFactorial[leftSize]) % MOD;
        count = (count * inverseFactorial[rightSize]) % MOD;

        if (l !== -1) count = (count * ways[l]) % MOD;
        if (r !== -1) count = (count * ways[r]) % MOD;

        ways[i] = count;
