function removeInvalidParentheses(s: string): string[] {
    const result: string[] = [];

    function search(
        current: string,
        scanStart: number,
        removeStart: number,
        open: string,
        close: string
    ): void {
        let balance = 0;

        for (let i = scanStart; i < current.length; i++) {
            if (current[i] === open) balance++;
            else if (current[i] === close) balance--;

            if (balance >= 0) continue;

            for (let j = removeStart; j <= i; j++) {
                if (
                    current[j] === close &&
