    const chars2 = Array.from(s2, c => c.charCodeAt(0) - 97);

    const dfs = (i: number, j: number, length: number): boolean => {
        const key = (length * n + i) * n + j;
        if (memo[key] !== 0) return memo[key] === 1;

        const counts = new Int32Array(26);
        let identical = true;

