function canPartitionKSubsets(nums: number[], k: number): boolean {
    const total = nums.reduce((sum, num) => sum + num, 0);
    if (total % k !== 0) return false;
    if (k === 1) return true;

    const target = total / k;
    const values = nums.slice().sort((a, b) => a - b);
    const n = values.length;

    if (values[n - 1] > target) return false;

    const stateCount = 1 << n;
    const dp = new Int32Array(stateCount);
    dp.fill(-1);
    dp[0] = 0;

    for (let mask = 0; mask < stateCount; mask++) {
        if (dp[mask] === -1) continue;

        for (let i = 0; i < n; i++) {
            const bit = 1 << i;
            if ((mask & bit) !== 0) continue;

            const nextSum = dp[mask] + values[i];
            if (nextSum > target) break;

            const nextMask = mask | bit;
            if (dp[nextMask] === -1) {
                dp[nextMask] = nextSum % target;
            }
        }
    }

    return dp[stateCount - 1] === 0;
};
