class StreamChecker {
    private readonly edges = new Map<number, number>();
    private readonly terminal: boolean[] = [false];
    private readonly history: number[];
    private maxLength = 0;
    private position = 0;
    private size = 0;

    constructor(words: string[]) {
        // Store reversed words so queries can inspect the newest letters first.
        for (const word of words) {
            this.maxLength = Math.max(this.maxLength, word.length);
            let node = 0;

            for (let i = word.length - 1; i >= 0; i--) {
                const character = word.charCodeAt(i) - 97;
                const key = node * 26 + character;
                let child = this.edges.get(key);

                if (child === undefined) {
                    child = this.terminal.length;
                    this.terminal.push(false);
                    this.edges.set(key, child);
                }

                node = child;
            }

            this.terminal[node] = true;
        }

        this.history = new Array<number>(this.maxLength);
    }

    query(letter: string): boolean {
        // A circular buffer retains only the longest possible matching suffix.
        this.history[this.position] = letter.charCodeAt(0) - 97;
        this.position = (this.position + 1) % this.maxLength;
        this.size = Math.min(this.size + 1, this.maxLength);

        let node = 0;
        let index = this.position;

        for (let i = 0; i < this.size; i++) {
            index = (index - 1 + this.maxLength) % this.maxLength;

            const child = this.edges.get(node * 26 + this.history[index]);
            if (child === undefined) {
                return false;
            }

            node = child;
            if (this.terminal[node]) {
                return true;
