function earliestAndLatest(n: number, firstPlayer: number, secondPlayer: number): number[] {
    const memo = new Map<string, number[]>();

    function solve(size: number, first: number, second: number): number[] {
        if (first + second === size + 1) {
            return [1, 1];
        }

        // Reflect the row to merge symmetric states.
        if (first + second > size + 1) {
            [first, second] = [size + 1 - second, size + 1 - first];
        }

        const key = `${size},${first},${second}`;
        const cached = memo.get(key);
        if (cached !== undefined) {
            return cached;
        }

        const nextSize = Math.ceil(size / 2);
        const stride = nextSize + 1;

        // Encode counts of advancing players before first and before second.
        let states = new Set<number>([0]);

        for (let left = 1, right = size; left <= right; left++, right--) {
            let winners: number[];

            if (left === first || right === first) {
                winners = [first];
            } else if (left === second || right === second) {
                winners = [second];
            } else if (left === right) {
                winners = [left];
            } else {
                winners = [left, right];
            }

            const nextStates = new Set<number>();
            for (const winner of winners) {
                const increment =
                    (winner < first ? stride : 0) +
                    (winner < second ? 1 : 0);

                for (const state of states) {
                    nextStates.add(state + increment);
                }
            }
            states = nextStates;
        }

        let earliest = Infinity;
        let latest = 0;

        for (const state of states) {
            const nextFirst = Math.floor(state / stride) + 1;
            const nextSecond = (state % stride) + 1;
            const result = solve(nextSize, nextFirst, nextSecond);

            earliest = Math.min(earliest, result[0] + 1);
            latest = Math.max(latest, result[1] + 1);
        }

        const result = [earliest, latest];
        memo.set(key, result);
        return result;
    }

    return solve(n, firstPlayer, secondPlayer);
